#define main prior_residual_audit_main
#include "<evidence-home-1>/projects/AIMA-public-r1191-candidate/tools/audit_gdn_replay_domain.cpp"
#undef main

// This is only a sufficient admission audit. A failed aggregate range does
// not establish that any particular paired product is outside the domain.
struct Range {
    unsigned low=255,high=0;
    bool normal=true,nonzero=false;
    void word(unsigned value){
        const unsigned magnitude=value&0x7fffu;
        if(!magnitude)return;
        const unsigned exponent=magnitude>>7u;
        normal=normal && exponent && exponent<255u;
        nonzero=true;low=std::min(low,exponent);high=std::max(high,exponent);
    }
    void interval(unsigned a,unsigned b){
        require(a<=b && b<0x7f80u,"invalid residual BF16 interval");
        if(!b)return;
        // If zero is included, include every possible nonzero BF16 encoding
        // above it as well. This deliberately overapproximates FTZ unions.
        word(std::max(a,1u));word(b);
    }
};
bool product_domain(const Range& a,const Range& b){
    if(!a.normal || !b.normal)return false;
    if(!a.nonzero || !b.nonzero)return true;
    return a.low+b.low>=190u && a.high+b.high<=318u;
}
std::array<unsigned,2> residual_interval(uint16_t value,float decay){
    const unsigned magnitude=value&0x7fffu;
    require(magnitude<0x7f80u && std::isfinite(decay) && decay>=0.0f && decay<=1.0f,"residual source domain");
    const uint32_t center=magnitude<<16u;
    const uint32_t left=center>=0x8000u?center-0x8000u:0u,right=center+0x8000u;
    volatile float product_low=from(left)*decay,product_high=from(right)*decay;
    unsigned a=rounded(product_low)&0x7fffu,b=rounded(product_high)&0x7fffu;
    if((bits(product_low)&0x7f800000u)==0u || (bits(decay)&0x7f800000u)==0u)a=0u;
    require(a<=b,"nonmonotone residual interval");
    return {a,b};
}
int main(int argc,char** argv)try{
    require(argc==2,"requires verified original capture directory");
    require(std::fesetround(FE_TONEAREST)==0,"rounding mode");
    unsigned exponent_checks=0;
    for(unsigned a=1;a<255;++a)for(unsigned b=1;b<255;++b){
        Range x,y;x.word(a<<7u);y.word(b<<7u);
        require(product_domain(x,y)==(a+b>=190u && a+b<=318u),"product domain pair");
        if(a>=95u && a<=159u && b>=95u && b<=159u)require(product_domain(x,y),"old domain inclusion");
        ++exponent_checks;
    }
    Range zero,tiny,big;zero.word(0x8000u);tiny.word(1u);big.word(0x7f80u);
    require(product_domain(zero,zero) && !product_domain(tiny,zero) && !product_domain(big,zero),"excluded operand guard");
    const std::string root=argv[1];
    const auto w=read<uint16_t>(root,"full-w-bf16.bin",size_t(tokens)*4096);
    const auto k=read<uint16_t>(root,"full-k-normalized-bf16.bin",size_t(tokens)*2048);
    const auto h=read<uint16_t>(root,"full-chunk-state-bf16.bin",size_t(chunks)*524288);
    const auto v=read<uint16_t>(root,"full-v-new-bf16.bin",size_t(tokens)*4096);
    const auto g=read<float>(root,"full-g-cumsum-f32.bin",size_t(tokens)*32);
    const auto table=read<unsigned char>(root,"sm121-exp2-negative-f490940d.bin",qrt_sm121_exp2::table_bytes);
    require(qrt_sm121_exp2::valid_layout(table.data(),table.size()),"original table layout");
    std::vector<float> decay(size_t(tokens)*32);
    for(unsigned row=0;row<tokens;++row)for(unsigned head=0;head<32;++head){
        const unsigned last=std::min(tokens,((row/64)+1)*64)-1;
        volatile float difference=g[size_t(last)*32+head]-g[size_t(row)*32+head];
        volatile float argument=difference*1.4426950408889634074f;
        decay[size_t(row)*32+head]=qrt_sm121_exp2::evaluate(table.data(),argument);
    }
    std::vector<Range> wr(chunks*32u),kr(chunks*32u),hr(chunks*32u*16u),vr(chunks*32u*16u);
    for(size_t i=0;i<w.size();++i){const size_t row=i/128;wr[(row/32/64)*32+row%32].word(w[i]);}
    for(size_t i=0;i<k.size();++i){const size_t row=i/128,at=(row/16/64)*32+(row%16)*2;kr[at].word(k[i]);kr[at+1].word(k[i]);}
    for(size_t i=0;i<h.size();++i){const size_t column=i/128;hr[(column/128)*16+(column%128)/8].word(h[i]);}
    size_t zero_intervals=0,nonzero_intervals=0;
    for(size_t i=0;i<v.size();++i){
        const size_t row=i/4096,head=(i/128)%32,column=i%128;
        const auto interval=residual_interval(v[i],decay[row*32+head]);
        (interval[1]?nonzero_intervals:zero_intervals)++;
        vr[((row/64)*32+head)*16+column/8].interval(interval[0],interval[1]);
    }
    Flags failed_wh{},failed_kv{},failed{};
    unsigned chunk_wh=0,chunk_kv=0,chunk_either=0;
    for(unsigned at=0;at<chunks*32u;++at)for(unsigned col=0;col<16u;++col){
        const bool wh=product_domain(wr[at],hr[at*16+col]),kv=product_domain(kr[at],vr[at*16+col]);
        const uint16_t mask=uint16_t(1u<<col);
        if(!wh){failed_wh[at]|=mask;++chunk_wh;}
        if(!kv){failed_kv[at]|=mask;++chunk_kv;}
        if(!wh || !kv){failed[at]|=mask;++chunk_either;}
    }
    const auto wh=fold(failed_wh),kv=fold(failed_kv),all=fold(failed);
    unsigned full_bad=0;std::array<unsigned,segments> segment_bad{};
    for(unsigned s=0;s<segments;++s)for(unsigned head=0;head<32u;++head){
        segment_bad[s]+=pop(all[s*32+head]);if(s<7u)full_bad+=pop(all[s*32+head]);
    }
    std::printf("{\"kind\":\"original_gb10_gdn_product_domain_sufficient_audit\",\"exponent_pair_checks\":%u,\"operand_exponents\":[1,254],\"nonzero_product_exponent_sums\":[190,318],\"residual_interval_cells\":%zu,\"zero_intervals\":%zu,\"nonzero_intervals\":%zu,\"chunk_ctas\":{\"total\":57856,\"wh_not_certified\":%u,\"kv_not_certified\":%u,\"either_not_certified\":%u},\"full1024_segments\":{\"total\":3584,\"not_certified\":%u,\"admitted\":%u},\"all_segments\":{\"total\":4096,\"wh_not_certified\":%u,\"kv_not_certified\":%u,\"not_certified\":%u,\"admitted\":%u},\"not_certified_by_segment\":[",exponent_checks,v.size(),zero_intervals,nonzero_intervals,chunk_wh,chunk_kv,chunk_either,full_bad,3584u-full_bad,count(wh),count(kv),count(all),4096u-count(all));
    for(unsigned s=0;s<segments;++s)std::printf("%s%u",s?",":"",segment_bad[s]);
    std::printf("],\"unrounded_residual_observed\":false,\"aggregate_range_is_sufficient_only\":true,\"native_receipts_observed\":false,\"native_speed_observed\":false,\"inference_acceptance\":false}\n");
    return 0;
}catch(const std::exception& e){std::fprintf(stderr,"%s\n",e.what());return 1;}

#define main prior_residual_audit_main
#include "<evidence-home-1>/projects/AIMA-public-r1191-candidate/tools/audit_gdn_replay_domain.cpp"
#undef main
#include <atomic>
#include <thread>

struct Bounds{uint16_t low,high;};
Bounds interval(uint16_t value,float decay){
    const unsigned magnitude=value&0x7fffu;
    require(magnitude<0x7f80u && std::isfinite(decay) && decay>=0.0f && decay<=1.0f,"residual domain");
    const uint32_t center=magnitude<<16u,left=center>=0x8000u?center-0x8000u:0u,right=center+0x8000u;
    volatile float lo=from(left)*decay,hi=from(right)*decay;
    unsigned a=rounded(lo)&0x7fffu,b=rounded(hi)&0x7fffu;
    if((bits(lo)&0x7f800000u)==0u || (bits(decay)&0x7f800000u)==0u)a=0;
    require(a<=b,"nonmonotone interval");return {uint16_t(a),uint16_t(b)};
}
// Sufficient domain for the unchanged [-64,64] product-group carry proof.
// A subnormal input is permitted only when its contribution must truncate to
// zero after original alignment, whether scalar multiplication uses FTZ or not.
struct Group{
    int lower=-1000,upper=-1000,risk=-1000;
    bool valid=true,nonzero=false;
    void pair(uint16_t left,Bounds right){
        const unsigned a=left&0x7fffu,l=right.low&0x7fffu,h=right.high&0x7fffu;
        if(a>=0x7f80u || h>=0x7f80u){valid=false;return;}
        if(!a || !h)return;
        nonzero=true;
        const int ae=int(std::max(1u,a>>7u)),he=int(std::max(1u,h>>7u));
        upper=std::max(upper,ae+he-254);
        if(a>=128u && l>=128u)lower=std::max(lower,int(a>>7u)+int(l>>7u)-254);
        if(a<128u)risk=std::max(risk,ae+he-254);
        if(l<128u)risk=std::max(risk,ae+1-254);
    }
    bool admitted()const{return valid && (!nonzero || (lower>=-64 && upper<=64 && risk<=lower-27));}
};
int main(int argc,char**argv)try{
    require(argc==2,"requires verified capture directory");
    require(std::fesetround(FE_TONEAREST)==0,"rounding mode");
    const std::string root=argv[1];
    const auto w=read<uint16_t>(root,"full-w-bf16.bin",size_t(tokens)*4096);
    const auto k=read<uint16_t>(root,"full-k-normalized-bf16.bin",size_t(tokens)*2048);
    const auto h=read<uint16_t>(root,"full-chunk-state-bf16.bin",size_t(chunks)*524288);
    const auto v=read<uint16_t>(root,"full-v-new-bf16.bin",size_t(tokens)*4096);
    const auto g=read<float>(root,"full-g-cumsum-f32.bin",size_t(tokens)*32);
    const auto table=read<unsigned char>(root,"sm121-exp2-negative-f490940d.bin",qrt_sm121_exp2::table_bytes);
    require(qrt_sm121_exp2::valid_layout(table.data(),table.size()),"original table layout");
    std::vector<Bounds> residual(v.size());
    for(unsigned row=0;row<tokens;++row)for(unsigned head=0;head<32u;++head){
        const unsigned last=std::min(tokens,((row/64)+1)*64)-1;
        volatile float difference=g[size_t(last)*32+head]-g[size_t(row)*32+head];
        volatile float argument=difference*1.4426950408889634074f;
        const float decay=qrt_sm121_exp2::evaluate(table.data(),argument);
        for(unsigned col=0;col<128u;++col){const size_t i=(size_t(row)*32+head)*128+col;residual[i]=interval(v[i],decay);}
    }
    Flags failed_wh{},failed_kv{},failed{};
    std::atomic<unsigned> next{0};std::array<std::thread,4> workers;
    for(auto&worker:workers)worker=std::thread([&]{
        for(unsigned at=next.fetch_add(1);at<chunks*32u;at=next.fetch_add(1)){
            const unsigned chunk=at/32u,head=at%32u,first=chunk*64u,valid=std::min(64u,tokens-first);
            for(unsigned block=0;block<16u;++block){
                bool wh=true,kv=true;
                for(unsigned col=block*8u;col<block*8u+8u && wh;++col)
                    for(unsigned row=0;row<valid && wh;++row)for(unsigned base=0;base<128u && wh;base+=16u){
                        Group group;
                        for(unsigned j=0;j<16u;++j){
                            const auto right=h[size_t(chunk)*524288u+(head*128u+col)*128u+base+j];
                            group.pair(w[(size_t(first+row)*32u+head)*128u+base+j],{uint16_t(right&0x7fffu),uint16_t(right&0x7fffu)});
                        }
                        wh=group.admitted();
                    }
                for(unsigned col=block*8u;col<block*8u+8u && kv;++col)
                    for(unsigned feature=0;feature<128u && kv;++feature)for(unsigned base=0;base<64u && kv;base+=16u){
                        Group group;
                        for(unsigned j=0;j<16u && base+j<valid;++j)
                            group.pair(k[(size_t(first+base+j)*16u+head/2u)*128u+feature],residual[(size_t(first+base+j)*32u+head)*128u+col]);
                        kv=group.admitted();
                    }
                const uint16_t mask=uint16_t(1u<<block);
                if(!wh)failed_wh[at]|=mask;
                if(!kv)failed_kv[at]|=mask;
                if(!wh || !kv)failed[at]|=mask;
            }
        }
    });
    for(auto&worker:workers)worker.join();
    const auto ws=fold(failed_wh),ks=fold(failed_kv),all=fold(failed);
    unsigned full_bad=0;std::array<unsigned,segments> bad{};
    for(unsigned s=0;s<segments;++s)for(unsigned head=0;head<32u;++head){bad[s]+=pop(all[s*32u+head]);if(s<7u)full_bad+=pop(all[s*32u+head]);}
    std::printf("{\"kind\":\"original_gb10_gdn_k16_group_domain_sufficient_audit\",\"workers\":4,\"chunk_ctas\":{\"total\":57856,\"wh_not_certified\":%u,\"kv_not_certified\":%u,\"either_not_certified\":%u},\"full1024_segments\":{\"total\":3584,\"not_certified\":%u,\"admitted\":%u},\"all_segments\":{\"total\":4096,\"wh_not_certified\":%u,\"kv_not_certified\":%u,\"not_certified\":%u,\"admitted\":%u},\"not_certified_by_segment\":[",count(failed_wh),count(failed_kv),count(failed),full_bad,3584u-full_bad,count(ws),count(ks),count(all),4096u-count(all));
    for(unsigned s=0;s<segments;++s)std::printf("%s%u",s?",":"",bad[s]);
    std::printf("],\"actual_unrounded_residual_observed\":false,\"native_receipts_observed\":false,\"native_speed_observed\":false,\"inference_acceptance\":false}\n");
    return 0;
}catch(const std::exception&e){std::fprintf(stderr,"%s\n",e.what());return 1;}
